      <path d="M6 3.19313C6 1.77732 7.6087 0.963471 8.73977 1.80521L27.6406 15.8708C28.7905 16.7266 28.5318 18.5282 27.1678 19.0381L19.507 21.9015C19.1118 22.0492 18.7831 22.3486 18.5901 22.7386L14.7175 30.5592C14.0779 31.851 12.1934 31.644 11.8344 30.2415L6.64395 9.96752C6.23079 8.35246 6 6.7869 6 3.19313Z" stroke="white" strokeWidth="2.5" />
