const ChatInputAnimation: React.FC<ChatInputAnimationProps> = ({
  backgroundColor = "#FAF9F7",
  transparentBackground = false,
  durationInSeconds = 12,
  promptBoxScale = 1,
  promptText = "Malloy, help! Something's not adding up... supply chain numbers for our new distance shoe don't match what's in my forecast. Can you take a look?",
  buttonText = "Let's go",
  buttonColor = "#C66B4B",
  typingSpeed = 1,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const startTypingFrame = 15;
  const charsToType = Math.max(0, Math.floor((frame - startTypingFrame) / typingSpeed));
  const currentText = promptText.substring(0, charsToType);
  const typingFinishedFrame = startTypingFrame + (promptText.length * typingSpeed);
  const isTyping = frame >= startTypingFrame && frame < typingFinishedFrame;
  const showBlinkingCursor = frame < typingFinishedFrame + 30;
  const blinkOpacity = Math.floor(frame / 15) % 2 === 0 ? 1 : 0;

  // Cursor Movement Timings
  const moveStartFrame = typingFinishedFrame + 30;
  const moveDuration = 45;
  const moveProgress = spring({
    frame: frame - moveStartFrame,
    fps,
    config: { damping: 14, stiffness: 80, mass: 0.8 },
  });

  // Cursor Positions (Relative to container)
  const cursorStartX = 40; // 40% from left
  const cursorStartY = 60; // 60% from top
  const cursorEndX = 85;   // 85% from left (over button)
  const cursorEndY = 80;   // 80% from top (over button)

  const currentCursorX = interpolate(moveProgress, [0, 1], [cursorStartX, cursorEndX]);
  const currentCursorY = interpolate(moveProgress, [0, 1], [cursorStartY, cursorEndY]);

  // Click Animation Timings
  const clickStartFrame = moveStartFrame + moveDuration + 10;
  const clickDuration = 6;
  
  let clickScale = 1;
  let buttonScale = 1;

  if (frame >= clickStartFrame) {
    if (frame < clickStartFrame + clickDuration / 2) {
      // Pressing down
      const progress = interpolate(frame, [clickStartFrame, clickStartFrame + clickDuration / 2], [0, 1]);
      clickScale = interpolate(progress, [0, 1], [1, 0.9]);
      buttonScale = interpolate(progress, [0, 1], [1, 0.96]);
    } else if (frame < clickStartFrame + clickDuration) {
      // Releasing
      const progress = interpolate(frame, [clickStartFrame + clickDuration / 2, clickStartFrame + clickDuration], [0, 1]);
      clickScale = interpolate(progress, [0, 1], [0.9, 1]);
      buttonScale = interpolate(progress, [0, 1], [0.96, 1]);
    }
  }

  // Fade in main container
  const containerOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });
  const containerY = interpolate(frame, [0, 15], [20, 0], { extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter, sans-serif", justifyContent: "center", alignItems: "center" }}>
      
      {/* Main Chat Box Container */}
      <div
        style={{
          width: width * 0.65,
          minHeight: 340,
          backgroundColor: "#FFFFFF",
          borderRadius: 36,
          border: "1px solid #EAE8E4",
          boxShadow: "0px 10px 40px rgba(0,0,0,0.03)",
          padding: "48px 56px",
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          opacity: containerOpacity,
          transform: `translateY(${containerY}px) scale(${promptBoxScale})`,
          transformOrigin: "center",
          position: "relative",
          transition: "none",
        }}
      >
        {/* Text Area */}
        <div style={{ minHeight: 140, marginBottom: 40 }}>
          <span style={{ fontSize: 38, lineHeight: 1.4, color: "#2B2A29", letterSpacing: "-0.01em" }}>
            {currentText}
          </span>
          {showBlinkingCursor && (
            <span
              style={{
                display: "inline-block",
                width: 3,
                height: 40,
                backgroundColor: "#2B2A29",
                marginLeft: 4,
                verticalAlign: "middle",
                opacity: blinkOpacity,
                transition: "none",
              }}
            />
          )}
        </div>

        {/* Bottom Toolbar */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          
          {/* Left Controls */}
          <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 12,
                padding: "16px 20px",
                border: "1px solid #EAE8E4",
                borderRadius: 12,
                color: "#1F1F1F",
                fontWeight: 600,
                fontSize: 20,
              }}
            >
              <FolderIcon />
              Work in a folder
            </div>
            <div style={{ color: "#666", padding: 8 }}>
              <PlusIcon />
            </div>
          </div>

          {/* Right Action Button */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              backgroundColor: buttonColor,
              color: "white",
              padding: "18px 32px",
              borderRadius: 16,
              fontWeight: 600,
              fontSize: 24,
              transform: `scale(${buttonScale})`,
              transformOrigin: "center",
              transition: "none",
            }}
          >
            {buttonText}
            <ArrowIcon />
          </div>

        </div>

        {/* Simulated Mouse Cursor */}
        <div
          style={{
            position: "absolute",
            left: `${currentCursorX}%`,
            top: `${currentCursorY}%`,
            transform: `scale(${clickScale})`,
            transformOrigin: "top left",
            zIndex: 100,
            opacity: frame > moveStartFrame - 10 ? 1 : 0, // Show right before moving
            pointerEvents: "none",
            transition: "none",
            filter: "drop-shadow(0px 8px 12px rgba(0,0,0,0.15))" // Extra overall shadow
          }}
        >
          <CursorIcon />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ChatInputAnimation;